CREATE TABLE public.comm_organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comm_organizations TO authenticated; GRANT ALL ON public.comm_organizations TO service_role;
ALTER TABLE public.comm_organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.comm_org_members(org_id uuid NOT NULL REFERENCES public.comm_organizations(id), user_id uuid NOT NULL REFERENCES public.profiles(id), role text NOT NULL DEFAULT 'member', PRIMARY KEY(org_id,user_id));
GRANT SELECT ON public.comm_org_members TO authenticated; GRANT ALL ON public.comm_org_members TO service_role;
ALTER TABLE public.comm_org_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.trade_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.comm_organizations(id), partner_org_id uuid REFERENCES public.comm_organizations(id), created_by uuid NOT NULL, direction text NOT NULL, title text NOT NULL, vegetable text NOT NULL, quantity numeric NOT NULL, origin text NOT NULL, destination text NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', review_note text NOT NULL DEFAULT '', reviewed_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.trade_requests TO authenticated; GRANT ALL ON public.trade_requests TO service_role;
ALTER TABLE public.trade_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.comm_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.comm_organizations(id), kind text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', private boolean NOT NULL DEFAULT true, created_by uuid NOT NULL, harvest_id uuid REFERENCES public.harvests(id), request_id uuid REFERENCES public.trade_requests(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comm_conversations TO authenticated; GRANT ALL ON public.comm_conversations TO service_role;
ALTER TABLE public.comm_conversations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.comm_participants(conversation_id uuid NOT NULL REFERENCES public.comm_conversations(id), user_id uuid NOT NULL REFERENCES public.profiles(id), org_id uuid NOT NULL REFERENCES public.comm_organizations(id), last_read_at timestamptz NOT NULL DEFAULT '1970-01-01', muted boolean NOT NULL DEFAULT false, PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.comm_participants TO authenticated; GRANT ALL ON public.comm_participants TO service_role;
ALTER TABLE public.comm_participants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.comm_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.comm_organizations(id), conversation_id uuid REFERENCES public.comm_conversations(id), token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, invited_by uuid NOT NULL, accepted_by uuid, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comm_invitations TO authenticated; GRANT ALL ON public.comm_invitations TO service_role;
ALTER TABLE public.comm_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.comm_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.comm_conversations(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL DEFAULT '', parent_id uuid REFERENCES public.comm_messages(id), attachments jsonb NOT NULL DEFAULT '[]', mentions uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz);
GRANT SELECT ON public.comm_messages TO authenticated; GRANT ALL ON public.comm_messages TO service_role;
ALTER TABLE public.comm_messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX comm_messages_history ON public.comm_messages(conversation_id,created_at,id);
CREATE TABLE public.comm_reactions(message_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, reaction text NOT NULL);
GRANT SELECT ON public.comm_reactions TO authenticated; GRANT ALL ON public.comm_reactions TO service_role;
ALTER TABLE public.comm_reactions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.comm_member(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comm_org_members WHERE org_id=p_org AND user_id=auth.uid()) $$;
CREATE FUNCTION public.comm_manager(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comm_org_members WHERE org_id=p_org AND user_id=auth.uid() AND role='manager') $$;
CREATE FUNCTION public.comm_access(p_conversation uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id=p_conversation AND (EXISTS(SELECT 1 FROM comm_participants p WHERE p.conversation_id=c.id AND p.user_id=auth.uid()) OR (c.kind='channel' AND NOT c.private AND comm_member(c.org_id))) AND (c.harvest_id IS NULL OR EXISTS(SELECT 1 FROM harvests h WHERE h.id=c.harvest_id AND (h.farmer_id=auth.uid() OR is_staff(auth.uid())))) AND (c.request_id IS NULL OR EXISTS(SELECT 1 FROM trade_requests r WHERE r.id=c.request_id AND (comm_member(r.org_id) OR comm_member(r.partner_org_id))))) $$;
CREATE POLICY comm_org_read ON public.comm_organizations FOR SELECT TO authenticated USING(comm_member(id));
CREATE POLICY comm_members_read ON public.comm_org_members FOR SELECT TO authenticated USING(comm_member(org_id));
CREATE POLICY trade_read ON public.trade_requests FOR SELECT TO authenticated USING(comm_member(org_id) OR comm_member(partner_org_id));
CREATE POLICY comm_conversations_read ON public.comm_conversations FOR SELECT TO authenticated USING(comm_access(id));
CREATE POLICY comm_participants_read ON public.comm_participants FOR SELECT TO authenticated USING(comm_access(conversation_id));
CREATE POLICY comm_invitations_read ON public.comm_invitations FOR SELECT TO authenticated USING(invited_by=auth.uid() OR comm_manager(org_id));
CREATE POLICY comm_messages_read ON public.comm_messages FOR SELECT TO authenticated USING(comm_access(conversation_id));
CREATE POLICY comm_reactions_read ON public.comm_reactions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM comm_messages m WHERE m.id=message_id AND comm_access(m.conversation_id)));
CREATE POLICY comm_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='communication-files' AND EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id::text=split_part(name,'/',1) AND comm_access(c.id)));
CREATE POLICY comm_files_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='communication-files' AND split_part(name,'/',2)=auth.uid()::text AND EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id::text=split_part(name,'/',1) AND comm_access(c.id)));
CREATE POLICY comm_files_remove ON storage.objects FOR DELETE TO authenticated USING(bucket_id='communication-files' AND split_part(name,'/',2)=auth.uid()::text AND EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id::text=split_part(name,'/',1) AND comm_access(c.id)));
CREATE FUNCTION public.comm_notify_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO notifications(user_id,title,body,event_type,details) SELECT p.user_id,'New communication message','','communication',jsonb_build_object('conversationId',NEW.conversation_id) FROM comm_participants p WHERE p.conversation_id=NEW.conversation_id AND p.user_id<>NEW.sender_id AND NOT p.muted AND (p.user_id=ANY(NEW.mentions) OR EXISTS(SELECT 1 FROM comm_conversations c WHERE c.id=NEW.conversation_id AND c.kind='direct')) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER comm_message_notification AFTER INSERT ON public.comm_messages FOR EACH ROW EXECUTE FUNCTION public.comm_notify_message();